import{_ as e,o as i,c as a,a0 as n}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Serve a fleet of campaigns","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/serve-campaigns.md","filePath":"how-to/serve-campaigns.md"}'),t={name:"how-to/serve-campaigns.md"};function l(p,s,r,o,h,d){return i(),a("div",null,[...s[0]||(s[0]=[n(`<h1 id="serve-a-fleet-of-campaigns" tabindex="-1">Serve a fleet of campaigns <a class="header-anchor" href="#serve-a-fleet-of-campaigns" aria-label="Permalink to &quot;Serve a fleet of campaigns&quot;">​</a></h1><p><code>peregrin campaign run &lt;yaml&gt;</code> hosts exactly one campaign in the foreground — fine for development, but every <code>github-webhook</code> ingress node would want its own listener, so N campaigns collide on <code>127.0.0.1:29173</code>. <code>peregrin campaign serve</code> is the multi-campaign daemon: one process, N campaign definitions, <strong>one shared webhook listener</strong>.</p><h2 id="boot" tabindex="-1">Boot <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;Boot&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">peregrin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> campaign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> campaigns/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:29173</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /hook</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --history-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/peregrin/history</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --queue-store-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/share/peregrin/queues</span></span></code></pre></div><p><code>campaigns/</code> may be a directory of <code>*.yaml</code>/<code>*.yml</code> files or any mix of files and directories — every yaml found becomes one campaign. Campaign names come from each yaml&#39;s <code>name:</code> field, falling back to the file stem; names must be unique or <code>serve</code> refuses to boot.</p><p>Flags:</p><ul><li><code>--listen &lt;addr&gt;</code> — the shared webhook bind address (default <code>127.0.0.1:29173</code>). Only meaningful when at least one campaign uses <code>github-webhook</code>; otherwise no listener binds.</li><li><code>--path &lt;path&gt;</code> — webhook path on that listener (default <code>/hook</code>).</li><li><code>--history-dir &lt;dir&gt;</code> — per-campaign JSONL run history at <code>&lt;dir&gt;/&lt;campaign&gt;.jsonl</code> (same format as <code>campaign run --history</code>).</li><li><code>--queue-store-dir &lt;dir&gt;</code> — per-campaign durable supersede queue at <code>&lt;dir&gt;/&lt;campaign&gt;.db</code> (same sqlite store as <code>campaign run --queue-store</code>).</li></ul><p>Each campaign gets its own <code>RunSupervisor</code>, its own supersede policy, and its own queue/history namespace — a crash or restart of the process replays every campaign&#39;s durable queue independently.</p><h2 id="shared-ingress-demux" tabindex="-1">Shared ingress demux <a class="header-anchor" href="#shared-ingress-demux" aria-label="Permalink to &quot;Shared ingress demux&quot;">​</a></h2><p>All <code>github-webhook</code> nodes across all campaigns register <strong>routes</strong> into one shared listener instead of binding their own socket. The listener is owned by <code>campaign serve</code> (<code>--listen</code>/<code>--path</code>); per-node <code>listen</code>/<code>path</code> params are ignored in serve mode.</p><p>Routing is <strong>all-match by <code>repository.full_name</code></strong> against each campaign&#39;s <code>params.repos[].name</code>:</p><ul><li>A push is delivered to <em>every</em> campaign watching that repo.</li><li>If two campaigns watch the same repo with different webhook secrets, only the route(s) whose secret validates the <code>X-Hub-Signature-256</code> receive the event.</li><li><code>X-GitHub-Delivery</code> dedup is global across the listener — a redelivery is answered <code>200 duplicate</code> once, before fan-out.</li><li>A repo no campaign watches gets <code>404</code>, same as the single-campaign driver.</li><li>A campaign whose run has ended simply drops injections; if every matching route is closed the listener answers <code>503</code>.</li></ul><h2 id="shutdown" tabindex="-1">Shutdown <a class="header-anchor" href="#shutdown" aria-label="Permalink to &quot;Shutdown&quot;">​</a></h2><p>SIGTERM/SIGINT (or <code>systemctl stop</code>) triggers a cooperative drain: the listener stops accepting, each supervisor finishes its active run, pending queue entries persist through their <code>QueueStore</code>, and the process exits when every campaign has drained. Active runs are not killed — they run to completion exactly as <code>campaign run</code> would.</p><h2 id="systemd-unit" tabindex="-1">systemd unit <a class="header-anchor" href="#systemd-unit" aria-label="Permalink to &quot;systemd unit&quot;">​</a></h2><p><code>campaign serve</code> is a plain long-running process — drop it in a unit:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /etc/systemd/system/peregrin-campaigns.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Peregrin campaign fleet</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network-online.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=peregrin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/usr/local/bin/peregrin campaign serve /etc/peregrin/campaigns \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    --listen 127.0.0.1:29173 --path /hook \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    --history-dir /var/lib/peregrin/history \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    --queue-store-dir /var/lib/peregrin/queues</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RestartSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Graceful drain gets up to TimeoutStopSec (default 90s); raise it if</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># runs are long.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TimeoutStopSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=300</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peregrin-campaigns</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peregrin-campaigns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # per-run events print as [&lt;campaign&gt;] ...</span></span></code></pre></div><p><code>peregrin provision</code> / tamias manage host-level service lifecycle (install/deploy/uninstall of the <code>peregrin serve</code> hub); campaign serving is a workload, not a host service — keep the unit above (or equivalent) as the campaign-plane supervisor. If the hub and the campaign fleet share a host, run them as separate units.</p>`,19)])])}const g=e(t,[["render",l]]);export{k as __pageData,g as default};
